function buildL(){
  var tabs='';
  Object.keys(structLabels).forEach(function(k){tabs+='<button class="lab-tab'+(k===curStruct?' active':'')+'" onclick="switchStruct(\''+k+'\')">'+structLabels[k]+'</button>'});
  document.getElementById('labTabs').innerHTML=tabs;
  var subtabs='';
  if(curStruct==='ccvcc'){ccvccSubs.forEach(function(k){subtabs+='<button class="lab-subtab'+(k===curSub?' active':'')+'" onclick="switchSub(\''+k+'\')">'+ccvccSubLabels[k]+'</button>'})}
  document.getElementById('labSubtabs').innerHTML=subtabs;
  var words;
  if(curStruct==='ccvcc'){words=labCCVCC[curSub].words}
  else if(curStruct==='ccvccc'){words=labCCVCCC.words}
  else if(curStruct==='cccvcc'){words=labCCCVCC.words}
  else{words=labCCCVCCC.words}
  var vowels='aeiou';
  document.getElementById('labGrid').innerHTML=words.map(function(w,i){
    var word=w[0],emoji=w[1],len=word.length;
    var sb=findStartBlend(word);
    var ebLen=(curStruct==='ccvccc'||curStruct==='cccvccc')?3:2;
    var ebPos=len-ebLen;
    var j=0,colored='';
    while(j<len){
      if(sb&&j===0){colored+='<span class="sb-c">'+sb.blend+'</span>';j+=sb.len}
      else if(j>=ebPos){colored+='<span class="eb-c">'+word.substring(j)+'</span>';j=len}
      else if(vowels.indexOf(word[j])>=0){colored+='<span class="vw">'+word[j]+'</span>';j++}
      else{colored+='<span class="cn-c">'+word[j]+'</span>';j++}
    }
    return '<div class="lab-card" id="lc'+i+'" onclick="document.getElementById(\'lc'+i+'\').classList.toggle(\'flipped\');spk(\''+word+'\')"><div class="word" style="letter-spacing:3px">'+colored+'</div><div class="hint">'+emoji+'</div></div>';
  }).join('');
}

